from common import *
B='50蜜月奇遇.txt'
make('honeymoon_youth','蜜月事件中的年轻贵人',B,
'他是身份极其尊贵、外貌足以被公众认出的年轻男子，正文有意不公布姓名与国籍，不能把他对应成某个真实王室成员，也不是年轻人系列的同名主角。他没有实际政治权力，却希望凭自己的地位和影响力阻止非洲一个以奴役黑人为目标的政权成立。他瞒着母亲化装旅行，使用法语和德语，在葡萄牙租下海上魔鬼号独自远航。理想并没有消除经验上的不足：他在直布罗陀被街头劫匪拘禁，后来用酒瓶击昏看守脱逃，却因匆忙离港没有补足燃料。遇到木兰花与高翔后，他先想借飞机继续前行，遭拒便以身份发号施令，不愿承认勇气不足以改变政治局势。他有服役和射击优良的经历，也敢当面斥责持枪绑架自己的军人；然而对方仍把他当成可以用来装饰新政权的工具。空中逃脱与海上等待救援，使他亲历个人勇敢的边界。他最终主动承认高估了自己，接受回到母亲身边的决定。这份醒悟不应抹去他反对压迫的价值观，而应使他在新情境中更愿意衡量行动如何被别人利用。',
'获救返回罗马，与母亲团聚，承认此次独行可能反而帮助敌方。','语言、独立航行与基础军事训练','能化装行动、使用法语和德语、独自驾船，曾因军中射击成绩得到手枪。','没有实权或超常体能；有限社会经验易受抢劫，航行需要燃料，声望不能使持枪对手服从。',[(342,372,'母亲所述身份与化装行踪。'),(1746,1754,'被抢劫拘禁。'),(1842,1854,'打昏看守脱逃。'),(2012,2064,'目标与地位的局限。'),(2122,2128,'服役和射击经历。'),(2438,2456,'改变决定并团聚。')],
'希望以自身地位反对压迫并证明独立价值，终局学会把善意与实际后果同时衡量。',[('有人把他当孩子劝退','理想受到轻视','先辩论和抗拒，但会回应具体证据。'),('敌方以礼仪掩饰绑架','发现个人身份被当政治工具','公开斥责并寻求可信同伴协助。'),('已有事实显示行动有反效果','不再只是空泛否定','承认判断失误，调整路线而不放弃价值观。')],aliases=('身份特殊的年轻人',),scores=(2,0,0,2,2,2),tier='并')
make('honeymoon_mother','蜜月事件中的贵妇',B,
'这位贵妇住在罗马附近的宏伟古堡中，地位特殊到木兰花与高翔看见她的面孔便改变了原先拒绝委托的决定。正文始终隐去她的具体身份，因此卡中也只保留可证实的资源、母亲身份和行动。她能够派人在不同城市追踪两名新婚旅客的行程，用古老马车接他们进堡，最初却藏在屏风后，只愿给出儿子身高、语言和最后出现在葡萄牙的线索。这样的谨慎有政治原因，也妨碍实际寻找工作：两位受托人指出，没有身份和样貌便难以从全世界找出一个不断化装的人。她最终让他们看见自己，并以母亲的焦急请求协助。她不是单纯要保住尊荣，更难接受儿子自愿离家走入危险，甚至说宁愿相信他是受人胁迫。获救归来的儿子与她相拥时，这种私人情感才显露得最直接。她认为救援值得勋章，却因事件不能公开，只能送上私人感谢和一枚红宝石戒指。她的影响力来自地位与受雇人员，不能换算成全知情报网、强制控制儿子的权能，或让未被派出的国家武力自动参战。',
'在古堡与获救归来的儿子团聚，私下感谢救援者，继续保守事件身份。','保密委托与高层资源协调','能通过人员与旅行资料寻找受托者，提供隐秘会面、线索与私人报酬。','高位不等于知道儿子全部行踪；保密限制信息共享，没有已示个人战斗能力。',[(220,226,'沿旅行资料找受托者。'),(302,384,'屏风会谈和委托条件。'),(460,466,'母亲的担忧。'),(2452,2468,'团聚与私下谢礼。')],
'保护儿子与牵涉公共身份的秘密，在政治礼仪与母亲的焦急之间寻找可行办法。',[('儿子脱离可知行程','公开搜寻会扩大政治风险','选择能保密的外部协助者。'),('保密令委托无法执行','对方提出必要信息条件','逐步让出必要线索，而非无限隐瞒。'),('危机已经化解','不能公开表彰','以私人感谢承认帮助并保护约定。')],scores=(0,0,1,1,1,1),tier='纸')
make('fale_weiding','法勒·韦定',B,
'法勒·韦定以商人自称，在葡萄牙拥有性能良好的海上魔鬼号。他用不问用途的出租方式赚取高额报酬，明知客户可能从事非法活动，仍把自己只负责借船当作方便的界线。旧酒吧熟悉他的住处，他也住在摆设华丽的公寓，饮酒习惯既是日常欲望，也成了木兰花与高翔找到他的突破口。两人上门将他制住后，他先说一无所知，在刀刃和窒息威胁下才说明租船给一个操法语、德语的高个男子。他的确不知道租船者真正身份和目的地，叙述不能把这种有限信息补成幕后政治策划。访客离开后，他没有就此置身事外，而是致电另一方出卖来人的国别和查港方向，追问先前许诺的报酬。他仍觉得若早知道租客重要，就该多收租金，无法判断自己正在参与的危险规模。随后灭口者进入公寓，以装有消音器的手枪射中他的双眼之间，他当场死亡。这个人物的逻辑是以不追问换取交易便利，又以零碎情报追加利益；它使他成为秘密行动中的有效节点，也让他完全没有能力保障自己的安全。',
'泄露调查者行踪后遭灭口，公寓中中枪死亡。','灰色船只出租与消息交易','出租本人登记的船，利用不问用途的交易条件加价，并向另一方兜售客户相关信息。','不知道租客目的地；缺乏保护自己的武力或情报全貌，醉酒与逐利降低警觉。',[(550,580,'酒吧线索与被制。'),(604,662,'商人身份、出租模式和船名。'),(668,704,'卖消息及死亡。')],
'以不承担追问责任的方式赚钱，遇到重要人物便试图再卖一次消息。',[('陌生客户愿付高租金','船只可用且不需问用途','出租并把用途责任推给客户。'),('被强者压制逼问','生命受到直接威胁','交出自己确实知道的部分。'),('握有新线索','相信有人愿意付费','主动报信索酬，低估被灭口风险。')],roles=('阶段性对立者',),scores=(1,0,0,1,1,1),tier='纸',dead=True)
make('embassy_colonel','非洲使馆上校',B,
'这名头发花白的中年军官在葡萄牙的一座非洲国家使馆中办事，正文没有公布他的姓名与所属国名。他以职业外交家的笑容迎接被武力带来的木兰花和高翔，说是请他们合作，实际希望查清两人正在找谁，并通过软禁阻止寻找成功。他有二十多年的军队经历和丰富的特务经验，高翔试图突然击腹制住他时，他敏捷后跃，避免了近身挟持。他也不轻信蜜月旅行和国际警察关系的说法，因为没有外人知道两名旅客已被扣在使馆内。关押房间的摄像装置留着具有迷惑性的外露电线，主角最初以为切断监视，实际仍被观察。即使不审出答案，拖延本身也能达到他的目的，这是他一度占优的关键。但当木兰花真正破坏镜头并长时间保持沉默，他终于失去耐心，派人查看。两名囚徒逃到窗外引来街上记者，他的强硬又迅速变成让步：秘密扣押一旦曝光，职务与外交关系都会受损。最后他被迫放人，未见被捕或受审。终局卡保留这种对秘密与官位的依赖，不能给外交身份附加绝对不受干涉的规则。',
'扣押行动曝光风险升高，被迫让木兰花与高翔离开；后续处分不详。','军事身手与秘密拘禁运作','凭军旅经验躲开近身袭击，组织警卫、监视及拖延，善用信息不对称施压。','离开使馆便没有同样控制条件；耐性有限，害怕公开证据与职务后果，非法律或物理免疫。',[(816,942,'盘问、身份与躲开高翔拳击。'),(1130,1176,'监视和拖延目的。'),(1234,1284,'失去耐心并派人检查。'),(1396,1448,'因记者曝光风险放行。')],
'完成上级的秘密阻拦任务，同时保全使馆与自己的职务。',[('目标拒绝提供资料','关押条件仍由自己掌握','用拖延替代无效说服。'),('监视失效且长期无回应','担心控制出现漏洞','逐渐急躁，派人检查。'),('行动即将成为公开新闻','继续强硬会危及职务','允许离开并设法掩饰事件。')],roles=('反派',),scores=(3,0,1,3,2,3),tier='并')
for key,name,detail in [('henry_gibraltar','亨利','他在冷僻街道抢走青年身上的现金，留下同伙看守，又拿着钥匙和执照到船上搜寻更多财物。被高翔追上制住后，他供出藏人地点，却在途中喊附近四个流氓袭击两名追查者，企图借人数翻盘。'),('george_gibraltar','佐治','他负责看守被抢来的青年，原本注意到对方气势与众不同，却没有真正把人绑住。青年用酒瓶击昏他，醒来后反而发现自己被绑，面对返回的同伙只能解释失手经过。')]:
 make(key,name,B,
 f'{name}是直布罗陀街头抢劫拘禁事件的参与者，与特殊身份青年的政治对手并没有已证实的组织关系。{detail} 两名匪徒都只把受害者当作身上现钞很多、可能还有贵重物品的独行客，行动缺少对身份和后果的了解。他们的生活与藏身条件破败，不能因为偶然截住重要人物就拥有专业情报组织的水平。木兰花与高翔找到关押处时，青年已经逃离，现场只剩遭自己失误反制的看守。亨利愤怒责打佐治，佐治则反问为何当初不按建议绑人，两人的互相推责暴露了合作的松散。抢劫不仅使青年身处险境，也令他匆忙离港、没有补充燃料，但这不是劫匪预先设计的国际政治圈套。正文没有继续交代两人的司法结果，因此卡只保留这次犯罪、被制与计划失败，不补写被判刑或参加最后空中绑架。演绎时可让他在眼前利益和强者威胁之间摇摆，但不能复制高翔的水中追捕能力，也不能把受害者偶然脱困说成他主动放人。',
 '拘禁计划失败，被害青年自行脱逃；未交代后续司法结果。','街头抢劫与临时看守','与同伙合作针对独行旅客，靠威胁、抢取钥匙和临时拘禁获利。','缺少专业训练与可靠警戒，可被普通反击击昏或被更强对手控制，互相推责影响合作。',[(1732,1794,'亨利身份、抢劫和求同伙袭击。'),(1828,1856,'佐治失守及两匪争执。')],
 '从孤立旅客身上尽快取得钱财，危险逼近时优先摆脱责任。',[('发现带现金的独行客','缺少目击者','以暴力抢劫并搜寻追加财物。'),('遭到有力反抗或追查','无法单独压制对方','依赖同伙或在威胁下供述。'),('行动失败','可把责任推给另一人','争执责怪，难以保持一致说法。')],roles=('反派',),scores=(2,0,0,1,1,1),tier='纸')
make('honeymoon_abductor','无标志机队领队',B,
'这名四十岁左右的汉子率职业军人乘三架没有国籍标志的水上飞机截住青年与木兰花夫妇。他起初是唯一没有持枪的人，依靠二十余名部下包围目标，并以参加新政府成立典礼的邀请掩饰强制带走。他不否认自己执行上级命令，却把政治责任推给政治家；青年斥责没有制服和标志的军人时，他一度脸红，仍继续威逼。他既要利用贵客身份，也保留在拒绝合作时秘密杀人的手段，因而不能仅按礼貌行礼归为普通护送人员。木兰花要求三人一同登机，他先拒绝，得知所谓已与直布罗陀联系、又受到可能有人揭发的压力后才让步。飞行中，他说明会由补给机空中加油，并打算沿海避开高射炮火；这些是任务可调动的外部资源，不是个人移动速度或全球控制范围。他因轻视三名被看守者而提供降落伞与救生衣，未搜出木兰花保存的手枪。逃脱发生时，他在机舱中被她射中心口死亡。杀死领队并未自动停止其他枪手开火，说明部下不会在他倒下后全部失去行动力。',
'机上绑架失败，被木兰花射中心口死亡，所在飞机随后坠毁。','武装劫持指挥与外交话术','协调机队与军人包围，兼用邀请、威胁和有限让步迫使目标登机。','机队须有人员燃料与补给；不等于个人飞行，疏于搜身，普通子弹可致命。',[(2130,2180,'机队、军人和威胁。'),(2208,2234,'同机谈判。'),(2260,2286,'飞行风险、补给和救生设备。'),(2300,2336,'中枪及逃脱后继续射击。')],
'把重要人物强制带到典礼以完成上级任务，必要时消除见证者。',[('目标以地位抗拒','武装优势仍在','保持礼貌形式但继续威胁。'),('秘密行动可能被揭发','让步不妨碍运输','作有限妥协以降低风险。'),('被看守者提出安全要求','误以为其只因怕死','提供设备而低估其用于逃脱的可能。')],roles=('反派',),scores=(3,0,1,3,3,3),tier='并',dead=True)
cov(B,[('年轻贵人','honeymoon_youth','单书主角','独自政治行动、被救及观念转变。'),('贵妇','honeymoon_mother','单书主角','发起保密寻找儿子的委托。'),('法勒·韦定','fale_weiding','阶段性对立者','非法便利及出卖行踪。'),('使馆上校','embassy_colonel','反派','秘密拘禁与阻挠。'),('亨利','henry_gibraltar','反派','抢劫拘禁和反扑。'),('佐治','george_gibraltar','反派','看守被抢青年。'),('机队领队','honeymoon_abductor','反派','政治绑架与死亡威胁。'),('高翔','mulanhua_gao_xiang','系列主角','与木兰花结婚并共同救援。'),('安妮','mulanhua_annie','系列主角','面对婚后分离与独立生活。'),('穆秀珍','mulanhua_mu_xiuzhen','系列主角','婚礼和接机后的互动。'),('方局长','mulanhua_fang_director','跨书重要配角','婚礼及公开说明双方意愿。'),('云四风','mulanhua_yun_sifeng','跨书重要配角','婚礼协助。'),('云五风','mulanhua_yun_wufeng','跨书重要配角','送行。')],excluded=[('管家、引路人、直布罗陀接待官员与渔船人员','一次性委托传递或救援辅助，无独立主角线。'),('灭口枪手及其他警卫、劫匪、机队军人','匿名执行者，未提供足够独立身份；主要指挥与具名者已纳入。')],notes=['正文刻意隐去政治人物姓名国籍，不对应真实人物；青年与年轻人系列主角分开。','海上获救靠遇上渔船，不能记为主角必然幸运或无限水中续航。'])
